SELECT f.favorite_id, f.target_id, f.target_type, d.document_name AS "resourceName", d.library_id, d.content_source, d.creator_id AS "creatorUserId", d.document_type AS "resourceType", f.favorite_pin_order, f.created_time AS "favoriteTime", f.updated_time AS "pinTime", d.tenant_id, d.space_id FROM bt_dc_user_favorite f JOIN bt_dc_document d ON f.target_id = d.document_id WHERE f.user_id = #{userId}
AND f.tenant_id = #{tenantId}
AND f.space_id = #{spaceId} AND f.target_type = #{targetType} AND f.is_favorite_pinned = 'T' AND f.status_cd = '00A' AND d.status_cd = '00A' ORDER BY f.favorite_pin_order ASC, f.updated_time DESC

SELECT f.favorite_id, f.target_id, f.target_type, l.library_name AS "resourceName", l.library_icon AS "resourceIcon", l.color, (SELECT COUNT(*) FROM bt_dc_document WHERE library_id = l.library_id AND status_cd = '00A') AS "documentCount", l.creator_id AS "creatorUserId", f.favorite_pin_order, f.created_time AS "favoriteTime", f.updated_time AS "pinTime", l.tenant_id, l.space_id FROM bt_dc_user_favorite f JOIN bt_dc_document_library l ON f.target_id = l.library_id WHERE f.user_id = #{userId} AND f.space_id = #{spaceId}
AND f.tenant_id = #{tenantId}
AND f.target_type = #{targetType} AND f.is_favorite_pinned = 'T' AND f.status_cd = '00A' AND l.status_cd = '00A' ORDER BY f.favorite_pin_order ASC, f.updated_time DESC

SELECT f.favorite_id, f.target_id, f.target_type, k.knowledge_name AS "resourceName", k.creator_id AS "creatorUserId", f.favorite_pin_order, f.created_time AS "favoriteTime", f.updated_time AS "pinTime", k.color, k.knowledge_icon AS "resourceIcon", k.knowledge_id AS "resourceCode", k.tenant_id, k.space_id FROM bt_dc_user_favorite f JOIN bt_knowledge_base k ON f.target_id = k.kb_code WHERE f.user_id = #{userId} AND f.space_id = #{spaceId}
AND f.tenant_id = #{tenantId}
AND f.target_type = #{targetType} AND f.is_favorite_pinned = 'T' AND f.status_cd = '00A' ORDER BY f.favorite_pin_order ASC, f.updated_time DESC

SELECT * FROM ( SELECT f.favorite_id, f.target_id, f.target_type, d.document_name AS "resourceName", d.library_id, '' AS "contentSource", d.document_type AS "resourceType", NULL AS "resourceIcon", '' AS "color", 0 AS "documentCount", 0 AS "resourceCode", d.creator_id AS "creatorUserId", f.favorite_pin_order, f.created_time AS "favoriteTime", f.updated_time AS "pinTime", d.tenant_id, d.space_id FROM bt_dc_user_favorite f JOIN bt_dc_document d ON f.target_id = d.document_id WHERE f.user_id = #{userId}
AND f.tenant_id = #{tenantId}
AND f.space_id = #{spaceId}
AND f.target_type IN ('DOCUMENT','FOLDER') AND f.is_favorite_pinned = 'T' AND f.status_cd = '00A' AND d.status_cd = '00A' UNION ALL SELECT f.favorite_id, f.target_id, f.target_type, l.library_name AS "resourceName", '' AS "libraryId", '' AS "contentSource", '' AS "resourceType", l.library_icon AS "resourceIcon", l.color, (SELECT COUNT(*) FROM bt_dc_document d2 WHERE d2.library_id = l.library_id AND d2.status_cd = '00A') AS "documentCount", 0 AS "resourceCode", l.creator_id AS "creatorUserId", f.favorite_pin_order, f.created_time AS "favoriteTime", f.updated_time AS "pinTime", l.tenant_id, l.space_id FROM bt_dc_user_favorite f JOIN bt_dc_document_library l ON f.target_id = l.library_id WHERE f.user_id = #{userId}
AND f.tenant_id = #{tenantId}
AND f.space_id = #{spaceId}
AND f.target_type = 'LIBRARY' AND f.is_favorite_pinned = 'T' AND f.status_cd = '00A' AND l.status_cd = '00A' UNION ALL SELECT f.favorite_id, f.target_id, f.target_type, k.knowledge_name AS "resourceName", '' AS "libraryId", '' AS "contentSource", '' AS "resourceType", k.knowledge_icon AS "resourceIcon", k.color, 0 AS "documentCount", k.knowledge_id AS "resourceCode", k.creator_id AS "creatorUserId", f.favorite_pin_order, f.created_time AS "favoriteTime", f.updated_time AS "pinTime", k.tenant_id, k.space_id FROM bt_dc_user_favorite f JOIN bt_knowledge_base k ON f.target_id = k.kb_code WHERE f.user_id = #{userId}
AND f.tenant_id = #{tenantId}
AND f.space_id = #{spaceId}
AND f.target_type = 'KNOWLEDGE' AND f.is_favorite_pinned = 'T' AND f.status_cd = '00A' ) t
ORDER BY t.pinTime DESC
ORDER BY t."pinTime" DESC

SELECT f.favorite_id, f.target_id, f.target_type, d.document_name AS "resourceName", d.content_source, d.library_id, d.tenant_id, d.space_id, d.document_type AS "resourceType", d.creator_id AS "creatorUserId", f.is_favorite_pinned, f.created_time AS "favoriteTime", CASE WHEN f.is_favorite_pinned = 'T' THEN f.updated_time ELSE NULL END AS "pinTime", CASE WHEN EXISTS ( SELECT 1 FROM bt_dc_document_library lib WHERE lib.library_id = d.library_id AND lib.visibility_scope = 'PRIVATE' AND lib.is_builtin = 'T' AND lib.library_name = '我的文档' AND lib.status_cd = '00A' ) THEN 'T' ELSE 'F' END AS "myDoc" FROM bt_dc_user_favorite f JOIN bt_dc_document d ON f.target_id = d.document_id WHERE f.user_id = #{userId}
AND f.tenant_id = #{tenantId}
AND f.space_id = #{spaceId} AND d.space_id = #{spaceId}
AND f.target_type = #{targetType} AND f.status_cd = '00A' AND d.status_cd = '00A' AND f.favorite_pin_order = 0 ORDER BY f.is_favorite_pinned DESC, f.favorite_pin_order ASC, f.created_time DESC

SELECT f.favorite_id, f.target_id, f.target_type, l.library_name AS "resourceName", l.library_icon AS "resourceIcon", l.color, COUNT(d2.document_id) AS "documentCount", l.creator_id AS "creatorUserId", f.is_favorite_pinned, l.tenant_id, l.space_id, f.created_time AS "favoriteTime", CASE WHEN f.is_favorite_pinned = 'T' THEN f.updated_time ELSE NULL END AS "pinTime" FROM bt_dc_user_favorite f JOIN bt_dc_document_library l ON f.target_id = l.library_id LEFT JOIN bt_dc_document d2 ON d2.library_id = l.library_id AND d2.status_cd = '00A' WHERE f.user_id = #{userId}
AND f.tenant_id = #{tenantId}
AND f.space_id = #{spaceId} AND l.space_id = #{spaceId}
AND f.target_type = #{targetType} AND f.status_cd = '00A' AND l.status_cd = '00A' AND f.favorite_pin_order = 0 GROUP BY f.favorite_id, f.target_id, f.target_type, l.library_name, l.tenant_id, l.space_id, l.library_icon, l.creator_id, f.is_favorite_pinned, f.created_time, f.updated_time, l.color ORDER BY f.is_favorite_pinned DESC, f.favorite_pin_order ASC, f.created_time DESC

SELECT f.favorite_id, f.target_id, f.target_type, k.knowledge_name AS "resourceName", k.color, k.knowledge_icon AS "resourceIcon", k.creator_id AS "creatorUserId", k.knowledge_id AS "resourceCode", f.is_favorite_pinned, k.tenant_id, k.space_id, f.created_time AS "favoriteTime", CASE WHEN f.is_favorite_pinned = 'T' THEN f.updated_time ELSE NULL END AS "pinTime" FROM bt_dc_user_favorite f JOIN bt_knowledge_base k ON f.target_id = k.kb_code WHERE f.user_id = #{userId}
AND f.tenant_id = #{tenantId}
AND k.space_id = #{spaceId} AND f.space_id = #{spaceId}
AND f.target_type = #{targetType} AND f.status_cd = '00A' AND f.favorite_pin_order = 0 ORDER BY f.is_favorite_pinned DESC, f.favorite_pin_order ASC, f.created_time DESC

SELECT * FROM ( SELECT f.favorite_id, f.target_id, f.target_type, d.document_name AS "resourceName", '' AS "contentSource", d.library_id, d.space_id, d.tenant_id, d.document_type AS "resourceType", d.creator_id AS "creatorUserId", f.is_favorite_pinned, f.created_time AS "favoriteTime", CASE WHEN f.is_favorite_pinned = 'T' THEN f.updated_time ELSE NULL END AS "pinTime", NULL AS "resourceIcon", '' AS "color", 0 AS "documentCount", 0 AS "resourceCode", CASE WHEN EXISTS ( SELECT 1 FROM bt_dc_document_library lib WHERE lib.library_id = d.library_id AND lib.visibility_scope = 'PRIVATE' AND lib.is_builtin = 'T' AND lib.library_name = '我的文档' AND lib.status_cd = '00A' ) THEN 'T' ELSE 'F' END AS "myDoc" FROM bt_dc_user_favorite f JOIN bt_dc_document d ON f.target_id = d.document_id WHERE f.user_id = #{userId}
AND f.tenant_id = #{tenantId}
AND d.space_id = #{spaceId} AND f.space_id = #{spaceId}
AND f.target_type IN ('DOCUMENT','FOLDER') AND f.status_cd = '00A' AND d.status_cd = '00A' AND f.favorite_pin_order = 0 UNION ALL SELECT f.favorite_id, f.target_id, f.target_type, l.library_name AS "resourceName", '' AS "contentSource", l.library_id, l.space_id, l.tenant_id, '' AS "resourceType", l.creator_id AS "creatorUserId", f.is_favorite_pinned, f.created_time AS "favoriteTime", CASE WHEN f.is_favorite_pinned = 'T' THEN f.updated_time ELSE NULL END AS "pinTime", l.library_icon AS "resourceIcon", l.color, (SELECT COUNT(*) FROM bt_dc_document d2 WHERE d2.library_id = l.library_id AND d2.status_cd = '00A') AS "documentCount", 0 AS "resourceCode", 'F' AS "myDoc" FROM bt_dc_user_favorite f JOIN bt_dc_document_library l ON f.target_id = l.library_id WHERE f.user_id = #{userId}
AND f.tenant_id = #{tenantId}
AND l.space_id = #{spaceId} AND f.space_id = #{spaceId}
AND f.target_type = 'LIBRARY' AND f.status_cd = '00A' AND l.status_cd = '00A' AND f.favorite_pin_order = 0 UNION ALL SELECT f.favorite_id, f.target_id, f.target_type, k.knowledge_name AS "resourceName", '' AS "contentSource", '' AS "libraryId", k.space_id, k.tenant_id, '' AS "resourceType", k.creator_id AS "creatorUserId", f.is_favorite_pinned, f.created_time AS "favoriteTime", CASE WHEN f.is_favorite_pinned = 'T' THEN f.updated_time ELSE NULL END AS "pinTime", k.knowledge_icon AS "resourceIcon", k.color, 0 AS "documentCount", k.knowledge_id AS "resourceCode", 'F' AS "myDoc" FROM bt_dc_user_favorite f JOIN bt_knowledge_base k ON f.target_id = k.kb_code WHERE f.user_id = #{userId}
AND f.tenant_id = #{tenantId}
AND k.space_id = #{spaceId} AND f.space_id = #{spaceId}
AND f.target_type = 'KNOWLEDGE' AND f.status_cd = '00A' AND f.favorite_pin_order = 0 ) t
ORDER BY t.favoriteTime DESC
ORDER BY t."favoriteTime" DESC

